// Extract company name and prepare due diligence structure
const subject = $input.first().json.subject || '';
const companyName = subject.replace(/^Research on\s*/i, '').trim() || 'Unknown Company';
const projectId = $input.first().json.project?.id || $input.first().json.project;

// Define 20-section due diligence structure
const sections = [
