parameters.functionCode:
// Create individual tasks for each section requirement
const sectionData = $node['Split Into Sections'].json;
const userStoryId = $json.id;
const companyName = $node['Prepare DD Structure'].json.companyName;
const authToken = $node['Auth'].json.auth_token;

const tasks = sectionData.tasks.map((task, index) => ({
  subject: `${sectionData.name}: ${task}`,
  description: `**Task ${index + 1} for ${sectionData.name}**\n\n**Company:** ${companyName}\n**Objective:** ${task}\n\n**Assigned Roles:**\n- Maker: ${sectionData.roles.maker}\n- Checker: ${sectionData.roles.checker}\n- Approver: ${sectionData.roles.approver}\n- QA: ${sectionData.roles.qa}\n- Integrity Checker: ${sectionData.roles.integrity_checker}\n\n**Status:** Awaiting Research\n**Evidence Required:** Yes\n**Compliance Status:** Pending`,
  user_story: userStoryId,
  project: $node['Prepare DD Structure'].json.projectId,
  status: 1,
  priority: 1,
  severity: 1,
  type: 1
}));

return tasks.map(task => ({ json: { task, authToken } }));
